mapper.select:
SELECT * FROM (
SELECT t.ptnr_id::text AS ptnr_id,t.ptnr_no,t.ptnr_se_cd,t.ptnr_nm,t.biz_reg_no,t.ceo_nm,t.indty_cd,t.chrg_nm,t.chrg_tel_no,t.txinv_email_addr,t.use_yn,
COALESCE(k.cd_nm,t.ptnr_se_cd) AS "kindName",i.cd_nm AS "industryName",b.cd_nm AS bank_cd,t.acnt_no,t.dpstr_nm,
CASE WHEN t.ptnr_se_cd='VEND' THEN NULL ELSE (SELECT count(DISTINCT p.prj_id) FROM prj.prj p WHERE p.prj_stts_cd IN ('PLAN','RUN','HOLD') AND (p.cust_ptnr_id=t.ptnr_id OR (t.ptnr_se_cd='BOTH' AND EXISTS(SELECT 1 FROM asgn.asgn a JOIN mst.dev d ON d.dev_id=a.dev_id WHERE a.prj_id=p.prj_id AND d.vndr_ptnr_id=t.ptnr_id AND )))) END AS "projectCount",
(SELECT count(DISTINCT d.dev_id) FROM asgn.asgn a JOIN prj.prj p ON p.prj_id=a.prj_id JOIN mst.dev d ON d.dev_id=a.dev_id WHERE  AND ((t.ptnr_se_cd IN ('CUST','BOTH') AND p.cust_ptnr_id=t.ptnr_id) OR (t.ptnr_se_cd IN ('VEND','BOTH') AND d.vndr_ptnr_id=t.ptnr_id))) AS "assignmentPeopleCount"
FROM mst.ptnr t LEFT JOIN cmn.cd_dtl k ON k.cd_grp_id='PARTNER_KIND' AND k.dtl_cd=t.ptnr_se_cd LEFT JOIN cmn.cd_dtl i ON i.cd_grp_id='INDUSTRY' AND i.dtl_cd=t.indty_cd LEFT JOIN cmn.cd_dtl b ON b.cd_grp_id='BANK' AND b.dtl_cd=t.bank_cd

  AND t.ptnr_se_cd IN (#{kind},'BOTH')
  AND t.use_yn=#{useYn}
  AND (strpos(lower(t.ptnr_nm),lower(#{q})) > 0 OR replace(t.biz_reg_no,'-','')=replace(#{q},'-',''))
  AND t.ptnr_id IN #{id}
) exported ORDER BY ${order}
